class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        res = []
        for c in colsum:
            if c == 2:
                if upper <= 0 or lower <= 0:
                    return []
                res.append([1, 1])
                upper -= 1
                lower -= 1
            elif c == 1:
                if upper > 0:
                    res.append([1, 0])
                    upper -= 1
                elif lower > 0:
                    res.append([0, 1])
                    lower -= 1
                else:
                    return []
            else:
                res.append([0, 0])
        return res if upper == 0 and lower == 0 else []

