class Solution {
public:
    vector<vector<int>> reconstructMatrix(int upper, int lower, vector<int>& colsum) {
        vector<vector<int>> res;
        for (int c : colsum) {
            if (c == 2) {
                if (upper <= 0 || lower <= 0) return {};
                res.push_back({1, 1});
                upper--; lower--;
            } else if (c == 1) {
                if (upper > 0) { res.push_back({1, 0}); upper--; }
                else if (lower > 0) { res.push_back({0, 1}); lower--; }
                else return {};
            } else {
                res.push_back({0, 0});
            }
        }
        if (upper != 0 || lower != 0) return {};
        return res;
    }
};

