class Solution:
    def reconstructMatrix(self, upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
        twos = colsum.count(2)
        ones = colsum.count(1)
        if twos > upper or twos > lower or 2 * twos + ones != upper + lower:
            return []
        topOnes = upper - twos
        res = []
        for c in colsum:
            if c == 2:
                res.append([1, 1])
            elif c == 1:
                if topOnes > 0:
                    res.append([1, 0])
                    topOnes -= 1
                else:
                    res.append([0, 1])
            else:
                res.append([0, 0])
        return res

