    vector<vector<int>> reconstructMatrix(int upper, int lower, vector<int>& colsum) {
        long long twos = count(colsum.begin(), colsum.end(), 2);
        long long ones = count(colsum.begin(), colsum.end(), 1);
        if (twos > upper || twos > lower || 2 * twos + ones != (long long)upper + lower)
            return {};
        int topOnes = upper - (int)twos;
        vector<vector<int>> res;
        for (int c : colsum) {
            if (c == 2) res.push_back({1, 1});
            else if (c == 1) {
                if (topOnes > 0) { res.push_back({1, 0}); topOnes--; }
                else res.push_back({0, 1});
            } else res.push_back({0, 0});
        }
        return res;
    }
};

