        if (twos > upper || twos > lower || 2L * twos + ones != (long) upper + lower)
            return new ArrayList<>();
        int topOnes = upper - twos;
        List<List<Integer>> res = new ArrayList<>();
        for (int c : colsum) {
            if (c == 2) res.add(Arrays.asList(1, 1));
            else if (c == 1) {
                if (topOnes > 0) { res.add(Arrays.asList(1, 0)); topOnes--; }
                else res.add(Arrays.asList(0, 1));
            } else res.add(Arrays.asList(0, 0));
        }
        return res;
    }
}

